SELECT ?search ?item ?itemLabel ?ord ?electric WHERE {
  VALUES ?search { "Audi Q4 e-tron" "Audi e-tron" "BMW i3" "BMW i4" "Bmw iX" "Bmw iX1" "Bmw iX3" "Citroen e-C4" "Cupra Born" "Fiat 500e" "Ford Explorer EV" "Ford Mustang Mach-E" "Hyundai Ioniq 5" "Hyundai Kona Electric" "Jaguar I-Pace" "Kia EV6" "Kia Niro EV" "MG ZS EV" "MG4 EV" "Mercedes-Benz EQA" "Mercedes-Benz EQB" "Mercedes-Benz EQC" "Mini Electric" "Nissan Leaf" "Opel Corsa Electric" "Opel Mokka-e" "Peugeot e-2008" "Peugeot e-208" "Polestar 2" "Porsche Taycan" "Renault Megane E-Tech Electric" "Renault Zoe" "Skoda Enyaq" "Tesla Model 3" "Tesla Model Y" "Volkswagen ID.3" "Volkswagen ID.4" "Volkswagen e-Golf" "Volvo EX30" "Volvo XC40 Recharge" }
  SERVICE wikibase:mwapi {
    bd:serviceParam wikibase:endpoint "www.wikidata.org"; wikibase:api "EntitySearch";
      mwapi:search ?search; mwapi:language "en".
    ?item wikibase:apiOutputItem mwapi:item. ?ord wikibase:apiOrdinal true.
  }
  ?item wdt:P31 wd:Q3231690 .
  BIND(EXISTS { VALUES ?ev { wd:Q193692 wd:Q1076882 } ?item wdt:P279* ?ev } AS ?electric)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} ORDER BY ?search ?ord
